import{_ as d,o as a,c as e,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const q=JSON.parse(`{"title":"喜诗糖果（See's Candies）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/喜诗糖果.md","filePath":"03_companies/喜诗糖果.md"}`),o={name:"03_companies/喜诗糖果.md"};function l(i,t,h,n,s,u){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="喜诗糖果-see-s-candies" tabindex="-1">喜诗糖果（See&#39;s Candies） <a class="header-anchor" href="#喜诗糖果-see-s-candies" aria-label="Permalink to &quot;喜诗糖果（See&#39;s Candies）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>See&#39;s Candies</td></tr><tr><td>行业</td><td>食品/糖果零售</td></tr><tr><td>成立年份</td><td>1921年</td></tr><tr><td>总部</td><td>加利福尼亚州旧金山</td></tr><tr><td>伯克希尔持股</td><td>100%（通过蓝筹印花收购）</td></tr><tr><td>收购价格</td><td>2,500万美元（1972年）</td></tr><tr><td>收购时有形净资产</td><td>800万美元</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>高品质盒装巧克力制造与零售，在美国西部拥有约200家零售店。圣诞季是销售高峰，前四周占全年销量40%，利润75%；某些年份12月利润甚至占到全年的90%。</p><h2 id="时间线-1972年买入至今" tabindex="-1">时间线（1972年买入至今） <a class="header-anchor" href="#时间线-1972年买入至今" aria-label="Permalink to &quot;时间线（1972年买入至今）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>事件</th></tr></thead><tbody><tr><td><strong>1972</strong></td><td>蓝筹印花（伯克希尔控股约60%）以2,500万美元收购，原卖家要价3,000万美元，巴菲特出价2,500万美元后卖家接受。当时年税前利润约420万美元，税后约200万美元</td></tr><tr><td><strong>1972-1977</strong></td><td>税前利润从420万美元增长到1,260万美元，几乎未增加额外资本投入</td></tr><tr><td><strong>1983</strong></td><td>伯克希尔完成收购蓝筹印花剩余40%股份，喜诗糖果成为伯克希尔100%子公司。同年，巴菲特在股东信附录详细讨论喜诗的经济商誉案例，成为投资经典</td></tr><tr><td><strong>1991</strong></td><td>收购20周年：销售额从2,900万美元涨到1.96亿美元，税前利润从420万美元涨到4,240万美元。累计仅追加投入1,800万美元增量资本，累计4.1亿美元税前利润全部分配给母公司</td></tr><tr><td><strong>1999</strong></td><td>税前利润达到创纪录水平，营业利润率24%。自收购以来累计赚取8.57亿美元税前利润，仍仅需极少资本</td></tr><tr><td><strong>2006</strong></td><td>Chuck Huggins交棒，Brad Kinstler接任CEO</td></tr><tr><td><strong>2011</strong></td><td>创下8,300万美元税前收益纪录，自购买以来累计总额达到16.5亿美元。年末账面价值（扣除现金后）低于零</td></tr><tr><td><strong>2014</strong></td><td>截至收购42周年，累计产生19亿美元税前利润，增长仅需追加投资4,000万美元</td></tr></tbody></table><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><p>喜诗糖果是伯克希尔历史上最重要的收购之一，对巴菲特投资理念的转变产生了深远影响：</p><ol><li><p><strong>投资转折点</strong>：1972年收购喜诗是巴菲特从雪茄烟蒂投资转向购买优秀企业的关键转折点，帮助巴菲特真正理解了查理·芒格一直倡导的&quot;以公平价格购买优秀企业&quot;的投资哲学。</p></li><li><p><strong>重要性评价</strong>：&quot;1972年是伯克希尔的转折点（尽管我偶有倒退——记得我1975年购买Waumbec）。当时我们有机会为蓝筹印花购买喜诗糖果——一家查理、我和伯克希尔均有大股份的公司，后来并入伯克希尔。&quot; —— 2014年股东信</p></li><li><p><strong>幸运的收购</strong>：&quot;二十年前，1972年一月三日，蓝筹印花买了喜诗糖果，当时卖家要四千万，企业净现金一千万，所以实际卖价三千万，查理和我那时候还不懂经济特许经营权，我们看七百万净资产，我们出价两千五百万，就不动了，卖家居然接受了，我们幸运。&quot; —— 1991年股东信</p></li><li><p><strong>投资课堂</strong>：通过观察喜诗糖果的经营，巴菲特获得了关于强大品牌价值的企业教育，开阔了他对许多其他有利可图投资的眼界。喜诗产生的超额现金帮助伯克希尔购买了更多其他企业，形成了良性的资本循环。</p></li></ol><blockquote><p>&quot;迄今，喜诗糖果已产生19亿美元税前利润，其增长仅需追加投资4,000万美元。喜诗糖果因此能够分配巨额资金，帮助伯克希尔购买其他业务，这些业务反过来又产生大量可分配利润。（想象兔子繁殖。）此外，通过观察喜诗糖果的行动，我获得了关于强大品牌价值的企业教育，开阔了我对许多其他有利可图投资的眼界。&quot; —— 2014年股东信</p></blockquote><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-强大的消费者特许权" tabindex="-1">1. 强大的消费者特许权 <a class="header-anchor" href="#_1-强大的消费者特许权" aria-label="Permalink to &quot;1. 强大的消费者特许权&quot;">​</a></h3><ul><li>产品质量口碑卓越，大多数巧克力爱好者更喜欢喜诗糖果，胜过两倍三倍价格的巧克力</li><li>节日送礼首选品牌，在西部市场获得巨大的边际偏好</li><li>极高的客户忠诚度，曾出现因门店搬迁顾客集体抗议迫使房东让步的案例</li></ul><h3 id="_2-经济商誉价值" tabindex="-1">2. 经济商誉价值 <a class="header-anchor" href="#_2-经济商誉价值" aria-label="Permalink to &quot;2. 经济商誉价值&quot;">​</a></h3><ul><li>经典案例：经济商誉vs会计商誉（见<a href="/search?q=商誉经济学">商誉经济学</a>，1983年股东信附录）</li><li>会计商誉从收购之日起不断摊销减少，但经济商誉实际上一直在不规则但非常显著地增长</li><li>由于通胀，经济商誉的名义价值会持续增长，是通胀年代最好的资产类型</li></ul><h3 id="_3-极致的资本效率" tabindex="-1">3. 极致的资本效率 <a class="header-anchor" href="#_3-极致的资本效率" aria-label="Permalink to &quot;3. 极致的资本效率&quot;">​</a></h3><ul><li>增长不需要追加大量资本，几乎所有盈利都可以返还母公司</li><li>到2011年末，扣除现金后账面价值低于零，仍能产生8,300万美元税前利润</li><li>伯克希尔可以用这些现金投资其他机会，创造了巨大的复利效应</li></ul><blockquote><p>&quot;我们相信大多数巧克力爱好者，更喜欢喜诗糖果，胜过两倍三倍价格的巧克力。（就像股票一样，价格和价值是两回事：价格是你付出的，价值才是你得到的。）&quot; —— 1983年股东信</p></blockquote><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;喜诗糖果拥有非常有价值的消费者特许权。&quot; —— 1981年股东信</p></blockquote><blockquote><p>&quot;在约2,000万净有形资产上，喜诗能税后赚1,300万美元。&quot; —— 1981年股东信</p></blockquote><blockquote><p>&quot;经济商誉让企业在有形净资产上获得超额回报。喜诗是典型案例。&quot; —— 1983年股东信附录</p></blockquote><blockquote><p>&quot;二十年后，喜诗糖果销售额从两千九百万涨到一亿九千六百万，税前利润从四百二十万涨到四千二百四十万，我们一共只投了一千八百万增量资本，就是原来七百万，后来一共两千五百万，剩下四亿一千万税前利润都分给我们了，所以你看，我们买了喜诗糖果，真的学到很多，我们更懂怎么评价特许经营权了，我们后来很多赚钱投资都是从喜诗糖果经验学到的。&quot; —— 1991年股东信</p></blockquote><blockquote><p>&quot;当他74岁，税前利润（以百万美元计）大约是他年龄的100%。发现了这种数学关系——让我们称之为&#39;哈金斯定律&#39;——查理和我现在一想到查克的生日就兴奋不已。&quot; —— 1999年股东信</p></blockquote><blockquote><p>&quot;控制喜诗糖果的家族要价3,000万美元，查理正确地说它值那么多。但我不想付超过2,500万美元，即使那个数字我也不太热衷。（三倍有形净资产的价格让我倒吸一口凉气。）我的错误谨慎可能毁掉一次绝佳购买。但幸运的是，卖方决定接受我们2,500万美元的出价。&quot; —— 2014年股东信</p></blockquote><blockquote><p>&quot;迄今，喜诗糖果已产生19亿美元税前利润，其增长仅需追加投资4,000万美元。喜诗糖果因此能够分配巨额资金，帮助伯克希尔购买其他业务，这些业务反过来又产生大量可分配利润。（想象兔子繁殖。）&quot; —— 2014年股东信</p></blockquote><blockquote><p>&quot;百年后，客户传递给伯克希尔的信息依然清晰：&#39;别动我的糖果。&#39;&quot; —— 2020年股东信</p></blockquote><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>销售额</th><th>税前利润</th><th>税后利润</th><th>有形净资产</th><th>备注</th></tr></thead><tbody><tr><td>1972（收购年）</td><td>2,900万</td><td>420万</td><td>200万</td><td>800万</td><td>ROE 25%</td></tr><tr><td>1977</td><td>-</td><td>1,260万</td><td>-</td><td>-</td><td>增长几乎无资本投入</td></tr><tr><td>1979</td><td>-</td><td>760万</td><td>-</td><td>-</td><td>数据来自财报</td></tr><tr><td>1981</td><td>-</td><td>2,189万</td><td>-</td><td>-</td><td></td></tr><tr><td>1982</td><td>-</td><td>2,388万</td><td>-</td><td>1,424万</td><td></td></tr><tr><td>1983</td><td>1.36亿</td><td>-</td><td>1,300万</td><td>2,000万</td><td></td></tr><tr><td>1988</td><td>-</td><td>3,250万</td><td>-</td><td>-</td><td>12月赚了全年利润90%</td></tr><tr><td>1991</td><td>1.96亿</td><td>4,240万</td><td>-</td><td>2,500万</td><td>累计税前利润4.1亿全部分配</td></tr><tr><td>1999</td><td>-</td><td>-</td><td>-</td><td>-</td><td>营业利润率24%，累计税前8.57亿</td></tr><tr><td>2003</td><td>-</td><td>5,900万</td><td>-</td><td>-</td><td></td></tr><tr><td>2011</td><td>-</td><td>8,300万</td><td>-</td><td>低于零（扣除现金后）</td><td>累计税前16.5亿</td></tr><tr><td>2014</td><td>-</td><td>-</td><td>-</td><td>仅追加投资总计4,000万</td><td>累计税前19亿</td></tr></tbody></table><h3 id="季节性特征" tabindex="-1">季节性特征 <a class="header-anchor" href="#季节性特征" aria-label="Permalink to &quot;季节性特征&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时期</th><th>销量占比</th><th>利润占比</th></tr></thead><tbody><tr><td>圣诞前四周</td><td>40%</td><td>75%</td></tr><tr><td>其他时段</td><td>60%</td><td>25%</td></tr><tr><td>极端情况（1988年）</td><td>-</td><td>12月占90%</td></tr></tbody></table><h2 id="管理团队" tabindex="-1">管理团队 <a class="header-anchor" href="#管理团队" aria-label="Permalink to &quot;管理团队&quot;">​</a></h2><h3 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>任期</th><th>贡献</th></tr></thead><tbody><tr><td>Mary See</td><td>创始人</td><td>1921-</td><td>创立配方和品牌</td></tr><tr><td><a href="/search?q=Chuck_Huggins">Chuck_Huggins</a></td><td>总经理/CEO</td><td>1972-2006</td><td>34年任期，利润增长十倍以上，建立客户导向文化</td></tr><tr><td>Brad Kinstler</td><td>CEO</td><td>2006-至今</td><td>将公司带到新高度，2011年创下8,300万税前利润纪录</td></tr></tbody></table><h3 id="管理特点" tabindex="-1">管理特点 <a class="header-anchor" href="#管理特点" aria-label="Permalink to &quot;管理特点&quot;">​</a></h3><ul><li>始终保持客户导向的企业文化，对产品质量绝不妥协</li><li>砍掉不受欢迎产品时，如果顾客反对会立刻加回</li><li>直营模式保证服务质量，顾客服务质量行业领先</li><li>几乎所有门店都直营，不加盟，保持统一高品质体验</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1973, 1974, 1977, 1978, 1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1992, 1993, 1994, 1996, 1997, 1999, 2003, 2005, 2009, 2010, 2011, 2013, 2014, 2015, 2020</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/内布拉斯加家具城">内布拉斯加家具城</a> - 同为经典收购案例</li><li><a href="/03_companies/蓝筹印花">蓝筹印花</a> - 收购主体</li><li><a href="/search?q=商誉经济学">商誉经济学</a> - 1983年附录，经济商誉经典案例</li><li><a href="/search?q=Chuck_Huggins">Chuck_Huggins</a> - 传奇CEO</li><li><a href="/03_companies/水牛城新闻">水牛城新闻</a> - 同期收购案例</li></ul><hr><p><em>最后更新：2026-04-16</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1973年/翻译">/01_letters/1973年/翻译</a></li><li><a href="/01_letters/1974年/翻译">/01_letters/1974年/翻译</a></li><li><a href="/01_letters/2000年/翻译">/01_letters/2000年/翻译</a></li><li><a href="/01_letters/2004年/翻译">/01_letters/2004年/翻译</a></li></ul>',46)])])}const b=d(o,[["render",l]]);export{q as __pageData,b as default};
